insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-why-won-t-my-neuronode-connect','NeuroNode','Connection','Why won’t my NeuroNode connect?','Confirm Bluetooth is on, Shake to Wake the NeuroNode, reopen the Controller App and try Connect to NeuroNode. If it still fails, use the Bluetooth reset guide.','#/aac/neuronode/help','published',1) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-neuronode-does-not-appear-in-bluetooth','NeuroNode','Connection','NeuroNode does not appear in Bluetooth','Shake to Wake first. If it was previously paired to another device, remove/forget the old pairing before reconnecting.','#/aac/neuronode/help','published',2) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-why-am-i-getting-a-weak-or-inconsistent-signal','NeuroNode','Signal','Why am I getting a weak or inconsistent signal?','Check placement and orientation, skin/electrode contact, and whether the selected muscle can produce a clear repeatable activation.','#/aac/neuronode/emg','published',3) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-what-do-the-neuronode-indicator-colours-mean','NeuroNode','Signal','What do the NeuroNode indicator colours mean?','Blue means searching for Bluetooth, green indicates a counted switch, yellow indicates low battery and red indicates an error state.','#/aac/neuronode/help','published',4) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-how-do-i-charge-neuronode','NeuroNode','Charging','How do I charge NeuroNode?','Place NeuroNode correctly on its charging plate and connect the charging plate to power.','#/aac/neuronode/get-started','published',5) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-neuronode-works-but-grid-3-does-not-respond','NeuroNode','Grid 3','NeuroNode works but Grid 3 does not respond','In Grid 3 go to Settings → Access → Switches → Connection → Change Key, then activate NeuroNode and save the detected key.','#/aac/neuronode/grid3','published',6) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neuronode-how-do-i-reset-bluetooth-scrub-neuronode','NeuroNode','Reset','How do I reset / Bluetooth scrub NeuroNode?','Use the Controller App scrub method when available. The manual pin method is an advanced recovery option and should be followed carefully.','#/aac/neuronode/help','published',7) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-eyegaze-eye-tracking-is-inaccurate','EyeGaze','Positioning','Eye tracking is inaccurate','Position the user approximately 45–60 cm from the display and keep the top of the screen around eye level before recalibrating.','#/aac/eyegaze-duo/positioning','published',8) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-eyegaze-eyegaze-camera-is-not-detected','EyeGaze','Connection','EyeGaze camera is not detected','Check both ends of the USB cable and confirm the camera is connected to the correct USB port/hub.','#/aac/eyegaze-duo/help','published',9) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-eyegaze-calibration-keeps-failing','EyeGaze','Calibration','Calibration keeps failing','Recheck position, lighting, user visibility and camera connection. Use the camera calibration software again after positioning is corrected.','#/aac/eyegaze-duo/positioning','published',10) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-uno-touch-grid-3-does-not-open','UNO Touch','Startup','Grid 3 does not open','On Windows, open Grid 3 manually if it does not launch automatically. On iOS, open Grid for iPad or the intended communication app.','#/aac/uno-touch','published',11) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-uno-touch-bluetooth-speaker-is-not-working','UNO Touch','Audio','Bluetooth speaker is not working','Confirm the speaker is powered on using the Play/Pause button and is connected in Bluetooth settings if required.','#/aac/uno-touch/help','published',12) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-trilogy-which-part-should-i-troubleshoot-first','Trilogy','Setup','Which part should I troubleshoot first?','Identify whether the issue is the Trilogy hardware, EyeGaze, NeuroNode or communication software, then use the linked subsystem guide.','#/aac/trilogy/help','published',13) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neurostrip-neurostrip-will-not-connect','NeuroStrip','Connection','NeuroStrip will not connect','Wake the device, open Connections, scan/discover devices and connect the correct NeuroStrip. Check Bluetooth if the device is not found.','#/neurostrip/help','published',14) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neurostrip-neurostrip-signal-is-erratic-or-very-low','NeuroStrip','Signal','NeuroStrip signal is erratic or very low','Check skin preparation, patch adherence, patch alignment and placement over the intended muscle. A charger/pod near-zero µV test and hard reset may be used for further troubleshooting.','#/neurostrip/help','published',15) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neurostrip-the-patch-will-not-adhere','NeuroStrip','Patch','The patch will not adhere','Repeat skin preparation and ensure the area is fully dry before applying the patch. Keep overdressing on the tail section only.','#/neurostrip/placement','published',16) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
insert into public.faqs(id,product,category,question,answer,related_route,status,sort_order) values ('faq-neurostrip-how-do-i-know-neurostrip-is-charging','NeuroStrip','Charging','How do I know NeuroStrip is charging?','Confirm the device is seated properly in the charging pod. The pod indicator flashes while charging and becomes solid when full according to the supplied charging guide.','#/neurostrip/get-started','published',17) on conflict(id) do update set product=excluded.product,category=excluded.category,question=excluded.question,answer=excluded.answer,related_route=excluded.related_route,status=excluded.status,sort_order=excluded.sort_order;
